import {mountWhitelistChecker} from './whitelist-checker.mjs';
import {mountQuestTasks} from './quest-tasks.mjs';
import {renderWhitepaper} from './technical-whitepaper.mjs';
function fitStudio(){document.documentElement.style.setProperty('--studio-scale',String(Math.min(1,document.documentElement.clientWidth/1672)));}window.addEventListener('resize',fitStudio);fitStudio();
import {mountStudio,pixelIcon} from './studio.mjs';
import {template,validateDraft} from './engine.mjs';
import {setLanguage,language} from './ui.mjs';
setLanguage(language);
const app=document.querySelector('#app');
function draft(){try{return validateDraft(JSON.parse(localStorage.getItem('fillout-pcb-reference-draft-v1')))||template();}catch{return template();}}
function stats(){const n=draft();return {nodes:n.length,quote:n.filter(x=>x.type==='nand').length,settle:n.filter(x=>x.type==='mem').length,wires:n.reduce((s,x)=>s+x.ins.filter(i=>i!==null).length,0),input:n.filter(x=>x.type==='input').length,output:n.filter(x=>x.type==='output').length};}
const heading=(n,title,desc)=>`<div class="local-heading"><p class="eyebrow">FILLOUT / ${n}</p><h1>${title}<span>✳</span></h1><p>${desc}</p></div>`;
function render(){queueMicrotask(decorateSections);const requested=location.hash.slice(1)||'home';const route=requested==='projects'?'mint':requested;document.body.dataset.page=route;document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+(route==='mint-fillout'?'mint':route));if(a.hash==='#'+(route==='mint-fillout'?'mint':route))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title='FillOut / '+route[0].toUpperCase()+route.slice(1);
if(route==='home'){app.innerHTML=`<section class="phone-home" aria-label="FillOut"><p class="phone-label">PARTS. WIRES. POSSIBILITIES.</p><h1>FILL<span>OUT</span></h1><p class="phone-intro">Build logic. Keep the state.</p><div class="phone-links"><a href="#studio"><span>Enter Studio</span><span aria-hidden="true">↗</span></a><a href="#quests"><span>Quests</span><span aria-hidden="true">↗</span></a><a href="#checker"><span>WL Checker</span><span aria-hidden="true">↗</span></a><a href="#mint"><span>FillOut Genesis</span><small>Mint not started yet</small></a></div></section><section class="home-hero"><a class="home-checker-entry" href="#checker"><svg class="checker-cable" viewBox="0 0 250 96" preserveAspectRatio="none" aria-hidden="true"><path class="checker-cable-shadow" d="M133 76 C168 86 225 78 228 57 S241 23 214 20 S186 5 156 13 S114 5 86 15 S34 4 23 22 S3 44 17 60 S37 84 67 77 S104 89 114 77"/><path class="checker-cable-base" d="M133 76 C168 86 225 78 228 57 S241 23 214 20 S186 5 156 13 S114 5 86 15 S34 4 23 22 S3 44 17 60 S37 84 67 77 S104 89 114 77"/><path class="checker-cable-flow" d="M133 76 C168 86 225 78 228 57 S241 23 214 20 S186 5 156 13 S114 5 86 15 S34 4 23 22 S3 44 17 60 S37 84 67 77 S104 89 114 77"/><path class="checker-cable-join" d="M114 77 133 76"/><g class="checker-cable-plug"><path d="M105 71h12v11h-12zM117 74h8m-8 5h8"/></g><path class="checker-cable-socket" d="M133 70h10v12h-10z"/><circle class="checker-cable-led" cx="23" cy="22" r="3"/></svg><span class="checker-entry-label">WL CHECKER ↗</span></a><a class="quest-entry quest-seal" href="#quests" aria-label="Open whitelist quests"><svg class="quest-seal-art quest-wire-art" viewBox="0 0 220 175" aria-hidden="true"><path class="quest-wire-shadow" d="M165 129 C192 135 210 117 199 102 S205 71 185 65 S190 30 164 39 S138 11 117 26 S81 10 70 32 S30 21 36 49 S9 67 25 86 S8 118 39 125 S54 156 78 140 S109 160 126 142 S145 139 150 133"/><path class="quest-wire-base" d="M165 129 C192 135 210 117 199 102 S205 71 185 65 S190 30 164 39 S138 11 117 26 S81 10 70 32 S30 21 36 49 S9 67 25 86 S8 118 39 125 S54 156 78 140 S109 160 126 142 S145 139 150 133"/><path class="quest-wire-current" d="M165 129 C192 135 210 117 199 102 S205 71 185 65 S190 30 164 39 S138 11 117 26 S81 10 70 32 S30 21 36 49 S9 67 25 86 S8 118 39 125 S54 156 78 140 S109 160 126 142 S145 139 150 133"/><path class="quest-wire-join" d="M150 133 165 129"/><g class="quest-wire-plug"><path d="M144 128h10v11h-10zM154 131h6m-6 5h6"/></g><path class="quest-wire-socket" d="M165 123h9v12h-9z"/><circle class="quest-wire-led" cx="36" cy="49" r="3"/></svg><span class="quest-entry-title">QUESTS</span></a><img class="home-image" src="home-art-clean.png" alt="FillOut: hand-cut lettering and a surreal illustrated creature in black, ivory and yellow"><div class="home-art-mask" aria-hidden="true"></div><div class="title-light" aria-hidden="true"></div><div class="home-stars" aria-hidden="true"><i style="--x:8%;--y:27%;--s:10px;--d:0ms">✧</i><i style="--x:18%;--y:57%;--s:7px;--d:80ms">✦</i><i style="--x:35%;--y:48%;--s:9px;--d:130ms">✧</i><i style="--x:65%;--y:34%;--s:7px;--d:60ms">✦</i><i style="--x:83%;--y:41%;--s:11px;--d:150ms">✧</i><i style="--x:94%;--y:58%;--s:8px;--d:90ms">✦</i><i style="--x:73%;--y:91%;--s:8px;--d:120ms">✧</i><i style="--x:12%;--y:79%;--s:9px;--d:40ms">✧</i></div><a class="home-art-link" href="#studio" aria-label="Enter Studio"><svg class="studio-scribble" viewBox="0 0 240 90" preserveAspectRatio="none" aria-hidden="true"><path d="M12 19 Q86 6 226 14 L229 73 Q110 85 10 74 Z"/><path class="studio-reflection" d="M12 19 Q86 6 226 14 L229 73 Q110 85 10 74 Z"/><path class="scribble-extra" d="M18 82 Q127 88 219 78"/></svg><span class="studio-invite">ENTER<br><strong>STUDIO</strong></span><span class="studio-arrow" aria-hidden="true">↗</span><span class="studio-spark" aria-hidden="true">✳</span><svg class="connect-circuit" viewBox="0 0 300 110" aria-hidden="true"><g class="power-source"><path class="source-body" d="M-25 75 L-3 72 12 84 10 105 -14 108 -27 96 Z"/><path class="source-pins" d="M-22 75v-7M-12 73v-7M-28 84h-7M-27 95h-7M-18 107v7M-6 107v7"/><path class="source-bolt" d="M-9 80 -18 92 -9 91 -13 101 1 86 -8 87Z"/><circle class="source-led" cx="5" cy="99" r="2"/></g><path class="cable-track" d="M10 90 H65 Q82 90 82 74 V62 Q82 46 98 46 H220"/><path class="cable-signal" d="M10 90 H65 Q82 90 82 74 V62 Q82 46 98 46 H220"/><g class="cable-plug"><path d="M207 38h14v16h-14zM221 42h8M221 50h8"/></g><path class="socket" d="M232 35h16v24h-16M248 46h24V22"/><circle class="circuit-lamp" cx="272" cy="15" r="7"/><path class="lamp-rays" d="M272 1v-5M258 5l-4-4M286 5l4-4M254 15h-5M290 15h5"/></svg><span class="circuit-status" aria-live="polite">make a connection</span></a></section><section class="home-bottom resource-links" aria-label="Project links"><a class="resource-link" href="#whitepaper"><span class="resource-symbol" aria-hidden="true">▤</span><span>Whitepaper</span><small>↗</small></a><a class="resource-link" href="#transparency"><span class="resource-symbol" aria-hidden="true">◇</span><span>Security &amp; Transparency</span><small>↗</small></a><a class="resource-link" href="https://github.com/Filloutt/fillout/issues" target="_blank" rel="noopener noreferrer"><span class="resource-symbol" aria-hidden="true">⚑</span><span>Report an issue</span><small>↗</small></a><a class="resource-link resource-social" href="https://x.com/Fillout_rh" target="_blank" rel="noopener noreferrer" aria-label="FillOut on X"><span aria-hidden="true">𝕏</span></a><a class="resource-link resource-social" href="https://github.com/Filloutt/fillout" target="_blank" rel="noopener noreferrer" aria-label="FillOut on GitHub"><svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M12 .8a11.4 11.4 0 0 0-3.6 22.2c.6.1.8-.2.8-.5v-2.1c-3.2.7-3.9-1.4-3.9-1.4-.5-1.3-1.3-1.6-1.3-1.6-1.1-.8.1-.8.1-.8 1.2.1 1.8 1.2 1.8 1.2 1.1 1.8 2.8 1.3 3.4 1 .1-.8.4-1.3.7-1.6-2.6-.3-5.3-1.3-5.3-5.6 0-1.2.4-2.2 1.2-3-.1-.3-.5-1.5.1-3.1 0 0 1-.3 3.1 1.2a10.7 10.7 0 0 1 5.8 0c2.2-1.5 3.1-1.2 3.1-1.2.6 1.6.2 2.8.1 3.1.8.8 1.2 1.8 1.2 3 0 4.3-2.7 5.3-5.3 5.6.4.4.8 1.1.8 2.1v3.2c0 .3.2.6.8.5A11.4 11.4 0 0 0 12 .8Z"/></svg></a></section>`;}else if(route==='studio'){mountStudio(app,()=>{});app.querySelector('.circuit-editor').insertAdjacentHTML('beforeend','<span class="watching-eye" aria-hidden="true"><svg viewBox="0 0 38 30"><ellipse cx="19" cy="15" rx="17" ry="12" fill="#10120b"/><g class="watching-pupil"><path d="M14 5h10v3h4v14h-4v3H14v-3h-4V8h4Z" fill="#bcb897"/><path d="M16 9h7v13h-7Z" fill="#15160e"/><path d="M17 10h3v4h-3Z" fill="#e9e3bc"/></g></svg></span>');app.querySelector('.studio-head h1').textContent='CIRCUIT BOARD / 01';app.querySelector('.studio-subtitle').textContent='Place a part. Trace a signal.';app.querySelector('.publish-section').hidden=true;app.querySelector('.panel-heading').textContent='ADD PARTS';app.querySelector('.palette-note').textContent='Click a part to add it';app.querySelectorAll('[data-add]').forEach(b=>{b.title='Add '+({input:'Input',nand:'Quote',mem:'Settle',output:'Output'}[b.dataset.add])+' to the board';b.setAttribute('aria-label',b.title);});app.querySelectorAll('[data-add]').forEach(b=>{b.querySelector('.component-symbol').innerHTML=pixelIcon(b.dataset.add);});app.querySelector('.canvas-wrap').insertAdjacentHTML('afterbegin','<span class="canvas-doodle" aria-hidden="true">✳<small>connect the dots.</small></span>');}
else if(route==='data'){app.innerHTML=heading('02 / DATA','DATA COMING AFTER DEPLOYMENT.','Token data will be added here after deployment.');}else if(route==='mint'){app.innerHTML=heading('03 / MINT','FILLOUT GENESIS.','Explore the collection.')+"<div class=\"project-cards\"><article class=\"local-project\"><a class=\"project-art fillout\" href=\"#mint-fillout\" aria-label=\"Open FillOut mint\"><span class=\"art-number\">FILLOUT / GENESIS COLLECTION</span></a><div class=\"project-caption\"><div><h2>FillOut <span class=\"genesis-badge\">GENESIS</span></h2><p>Quote + Settle</p></div><a class=\"project-mint-link\" href=\"#mint-fillout\">Mint ↗</a></div></article></div>";}
else if(route==='mint-fillout'){app.innerHTML=heading('FILLOUT / GENESIS','FILLOUT MINT.','Robinhood Chain · FillOut Genesis.')+`<div class="mint-preview"><section class="mint-preview-art"><span class="mint-collection-tag">GENESIS / 01</span><div class="mint-preview-chip" aria-hidden="true">${pixelIcon('nand')}</div><h2>FillOut <span class="genesis-badge">GENESIS</span></h2><div class="mint-supply" aria-live="polite"><span data-supply-part>Quote</span><p><strong data-supply-minted>0 / 117,392</strong><span>Minted / Total supply</span></p><p><strong data-supply-remaining>117,392</strong><span>Remaining</span></p></div></section><section class="mint-preview-controls" aria-label="Mint options"><p class="mint-label">PART</p><div class="mint-part-options"><button data-mint-part="Quote" aria-pressed="true">Quote</button><button data-mint-part="Settle" aria-pressed="false">Settle</button></div><div class="mint-price"><span>PRICE PER PART</span><strong>0.00005 <small>ETH</small></strong></div><p class="mint-label">QUANTITY</p><div class="mint-quantity-options">${[1,10,100].map(n=>'<button data-mint-quantity="'+n+'" aria-pressed="'+(n===1)+'">'+n+'</button>').join('')}</div><div class="mint-selection" aria-live="polite"><span>Selected</span><strong data-mint-selection>1 Quote</strong></div><button class="mint-closed-button" disabled>Mint not started yet</button></section></div>`;}
else if(route==='checker'){mountWhitelistChecker(app);}
else if(route==='quests'){mountQuestTasks(app);}
else if(route==='inventory'){app.innerHTML=heading('INVENTORY','YOUR INVENTORY.','Your FillOut parts and circuits will appear here when the collection launches.');}
else if(route==='whitepaper'){app.innerHTML=renderWhitepaper();}
else if(route==='protocol'){app.innerHTML=heading('PROTOCOL','PARTS. LOGIC. STATE.','How FillOut Studio works.')+'<div class="resource-document"><article><h2>Quote & Settle</h2><p>Quote is a two-input NAND gate. Settle stores one bit of state. Add parts, connect their ports and simulate the result in Studio.</p></article><article><h2>Design & simulation</h2><p>Wallet connection requests a readable signed acknowledgement. It does not authorize token approvals or blockchain transactions. Drafts are stored on this device. Export a draft to keep a separate copy.</p></article><article><h2>Mint & fees</h2><p>FillOut has 150,000 lifetime parts: 140,000 public mint and 10,000 team circuit parts. Mint price is 0.00005 ETH per part on Robinhood Chain. Gas is separate. Dates, sale-phase limits and final addresses will be published before mint opens.</p></article><a class="link-button" href="#home">← Back home</a></div>';}
else if(route==='transparency'){app.innerHTML=heading('SECURITY & TRANSPARENCY','KNOW WHAT YOU CONNECT TO.','Project resources and the current preview status.')+'<div class="resource-document"><article><h2>Release status</h2><p>FillOut Studio supports circuit design and simulation. Wallet connection uses a readable signed acknowledgement. Mint has not opened. The planned protocol uses irreversible part burning, 150,000 lifetime FillOut parts and a 0.00005 ETH mint price.</p></article><article><h2>Source & reporting</h2><p>The project repository and issue tracker are linked below. Published releases and issue reports can be reviewed in the repository.</p><p><a href="https://github.com/Filloutt/fillout" target="_blank" rel="noopener noreferrer">GitHub repository ↗</a> &nbsp; <a href="https://github.com/Filloutt/fillout/issues" target="_blank" rel="noopener noreferrer">Report an issue ↗</a></p></article><article><h2>Before launch</h2><p>Final contract addresses and permissions will be published before activation. Team parts are unlocked and committed to circuit construction rather than sale. Team-circuit rewards are allocated 50% to manual liquidity support and 50% to platform and community expenses. No independent audit is claimed. VRAM mining is not active.</p></article><a class="link-button" href="#home">← Back home</a></div>';}
else {location.hash='studio';}}
let connecting=false;
document.addEventListener('click',event=>{const link=event.target.closest('.home-art-link');if(!link)return;event.preventDefault();if(connecting)return;connecting=true;link.classList.add('is-connecting');link.setAttribute('aria-busy','true');link.querySelector('.circuit-status').textContent='connecting…';const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;setTimeout(()=>{if(!link.isConnected){connecting=false;return;}link.classList.add('is-connected');link.closest('.home-hero')?.classList.add('stars-lit');link.querySelector('.circuit-status').textContent='connected ✓';},reduced?0:350);setTimeout(()=>{connecting=false;if(link.isConnected)location.hash='studio';},reduced?250:1150);});
let pageTransition=0,pageAnimation=null;
window.addEventListener('hashchange',async()=>{connecting=false;const ticket=++pageTransition;pageAnimation?.cancel();app.inert=true;
if(matchMedia('(prefers-reduced-motion: reduce)').matches){window.scrollTo({top:0,left:0,behavior:'instant'});render();fitStudio();app.inert=false;return;}
const currentOpacity=getComputedStyle(app).opacity;pageAnimation=app.animate([{opacity:currentOpacity},{opacity:0}],{duration:220,easing:'cubic-bezier(.4,0,1,1)',fill:'forwards'});await pageAnimation.finished.catch(()=>{});if(ticket!==pageTransition)return;
window.scrollTo({top:0,left:0,behavior:'instant'});render();fitStudio();pageAnimation.cancel();pageAnimation=app.animate([{opacity:0},{opacity:1}],{duration:420,easing:'cubic-bezier(.16,1,.3,1)',fill:'forwards'});await pageAnimation.finished.catch(()=>{});if(ticket!==pageTransition)return;pageAnimation.cancel();pageAnimation=null;app.inert=false;
});render();









function decorateSections(){
 const footer=document.querySelector('body > footer');if(footer&&!footer.dataset.links){footer.dataset.links='1';footer.classList.add('global-resources');footer.innerHTML='<a class="footer-wordmark" href="#home">FILLOUT</a><div class="global-resource-links"><a href="#whitepaper">Whitepaper</a><a href="#transparency">Security &amp; Transparency</a><a href="https://github.com/Filloutt/fillout/issues" target="_blank" rel="noopener noreferrer">Report an issue ↗</a><a href="https://x.com/Fillout_rh" target="_blank" rel="noopener noreferrer" aria-label="FillOut on X">𝕏</a><a href="https://github.com/Filloutt/fillout" target="_blank" rel="noopener noreferrer">GitHub ↗</a></div>';}
 const route=document.body.dataset.page;
 if(route==='data'){
  document.querySelectorAll('.stat-grid article').forEach((el,i)=>el.insertAdjacentHTML('beforeend','<span class="stat-icon" aria-hidden="true">'+pixelIcon(['input','output','nand','mem'][i])+'</span>'));
  const eye=document.querySelector('.big-star');if(eye)eye.innerHTML=pixelIcon('nand');
 }
 if(route==='mint'){
  document.querySelector('.project-art')?.insertAdjacentHTML('beforeend','<div class="project-circuit" aria-hidden="true"><span class="project-cable"></span><div class="project-chip">'+pixelIcon('nand')+'<small>QUOTE</small></div><div class="project-chip">'+pixelIcon('mem')+'<small>SETTLE</small></div></div>');
 }
}

let eyeFrame=0,eyeMouse={x:0,y:0};
document.addEventListener('pointermove',event=>{if(document.body.dataset.page!=='studio')return;eyeMouse={x:event.clientX,y:event.clientY};if(eyeFrame)return;eyeFrame=requestAnimationFrame(()=>{eyeFrame=0;const eye=document.querySelector('.watching-eye');if(!eye)return;const rect=eye.getBoundingClientRect(),dx=eyeMouse.x-(rect.left+rect.width/2),dy=eyeMouse.y-(rect.top+rect.height/2),distance=Math.hypot(dx,dy),strength=Math.min(1,distance/130);const pupil=eye.querySelector('.watching-pupil');pupil.style.transform='translate('+(distance?dx/distance*6*strength:0)+'px,'+(distance?dy/distance*4*strength:0)+'px)';});},{passive:true});
document.documentElement.addEventListener('pointerleave',()=>{const pupil=document.querySelector('.watching-pupil');if(pupil)pupil.style.transform='translate(0px,0px)';});




document.addEventListener('click',event=>{const button=event.target.closest('[data-wp-section]');if(button)document.getElementById('wp-'+button.dataset.wpSection)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});







document.addEventListener('click',event=>{const button=event.target.closest('[data-mint-part],[data-mint-quantity]');if(!button)return;const selector=button.hasAttribute('data-mint-part')?'[data-mint-part]':'[data-mint-quantity]';document.querySelectorAll(selector).forEach(el=>el.setAttribute('aria-pressed',String(el===button)));const part=document.querySelector('[data-mint-part][aria-pressed="true"]')?.dataset.mintPart;const quantity=document.querySelector('[data-mint-quantity][aria-pressed="true"]')?.dataset.mintQuantity;const label=document.querySelector('[data-mint-selection]');if(label)label.textContent=quantity+' '+part;const cap=part==='Settle'?32608:117392;const fmt=n=>n.toLocaleString('en-US');const supplyPart=document.querySelector('[data-supply-part]');if(supplyPart)supplyPart.textContent=part;const minted=document.querySelector('[data-supply-minted]');if(minted)minted.textContent='0 / '+fmt(cap);const remaining=document.querySelector('[data-supply-remaining]');if(remaining)remaining.textContent=fmt(cap);const chip=document.querySelector('.mint-preview-chip');if(chip)chip.innerHTML=pixelIcon(part==='Settle'?'mem':'nand');});





let questEntryBusy=false;
document.addEventListener('click',event=>{const link=event.target.closest('.quest-entry');if(!link||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();if(questEntryBusy)return;questEntryBusy=true;link.classList.add('quest-wire-connected');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;setTimeout(()=>{questEntryBusy=false;if(link.isConnected&&document.body.dataset.page==='home')location.hash='quests';},reduced?120:1050);});


window.addEventListener("fillout:language",()=>render());

// Join the checker cable before opening the destination. Modifier clicks keep native navigation.
let checkerEntryBusy=false;
document.addEventListener('click',event=>{const link=event.target.closest('.home-checker-entry');if(!link||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();if(checkerEntryBusy)return;checkerEntryBusy=true;link.setAttribute('aria-busy','true');link.classList.add('checker-joining');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;setTimeout(()=>{if(link.isConnected)link.classList.add('checker-connected');},reduced?0:300);setTimeout(()=>{checkerEntryBusy=false;if(link.isConnected&&document.body.dataset.page==='home')location.hash='checker';},reduced?120:1050);});
